{
  "technical_and_design_decisions": [
    "Add a new `undeployed` value to the existing Mesos SPI status enum and map it from the appropriate Mesos task state, preserving backward compatibility with the `unknown` state.",
    "Expose the existing `RabbitBindingCleaner` via a new REST endpoint in the current REST API module using Spring MVC, reusing existing security and serialization patterns.",
    "Optimize the YARN deployer by submitting module deployments concurrently (e.g., using a bounded executor) and reusing YARN client sessions to reduce overhead.",
    "Allow a Kafka partition key expression to be configured and applied even when there is only a single downstream module, leveraging native Kafka producer partitioning.",
    "Perform library upgrades (SHDP 2.2.1, SI 4.2.2.GA, Spring Boot, Spring Cloud Build) by updating managed versions in the parent POM and making minimal code changes to address deprecated APIs.",
    "Keep the codebase on Java 8 (consistent with Spring Boot 1.3 / SI 4.2 era) and do not adopt Java 17 or Spring Framework 6 for this increment.",
    "Document HSQL DB composed-job limitations in the existing AsciiDoc user guide rather than creating new doc artifacts."
  ],
  "assumptions": [
    "The introductory text about Spring Framework 6 and Java 17 is background context and does not apply to this increment, which targets an older Spring Boot 1.3 / SI 4.2 stack.",
    "The codebase is a multi-module Maven project (Spring XD / Spring Cloud Data Flow era) and the developer is already familiar with its structure.",
    "All required upgraded library versions are available in the organization's Maven repositories.",
    "Effort includes writing and updating automated unit/integration tests, but excludes independent QA, UAT, and production deployment.",
    "The current `unknown` Mesos status is not relied upon exclusively by external clients, so adding `undeployed` will not break contracts.",
    "Development environment (JDK, Maven, network access) is already provisioned; only a feature branch and local build setup are needed.",
    "The REST cleanup endpoint is for internal/admin use and can use the existing authentication mechanism."
  ],
  "activities": [
    {
      "activity_id": "A01",
      "activity_name": "Environment setup and branch creation",
      "activity_description": "Create a feature branch, configure local Maven build, and establish a baseline build before making changes.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A02",
      "activity_name": "Upgrade SHDP to 2.2.1 GA and align Spring/Hadoop versions",
      "activity_description": "Update parent POM dependency management to SHDP 2.2.1, move Spring and Hadoop versions to compatible recent ones, resolve compilation issues, and run module tests (U4).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A03",
      "activity_name": "Upgrade Spring Integration to 4.2.2.GA",
      "activity_description": "Update Spring Integration dependency to 4.2.2.GA, adjust any deprecated API usages, and verify integration tests (U5).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A04",
      "activity_name": "Upgrade Spring Boot and Spring Cloud Build revisions",
      "activity_description": "Update Spring Boot and Spring Cloud Build parent/plugin versions, fix configuration or plugin changes, and verify full build (U7).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A05",
      "activity_name": "Add undeployed status for Mesos SPI",
      "activity_description": "Add `undeployed` enum value to Mesos SPI status model, map from Mesos task state, update serialization, and add unit tests (U1).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A06",
      "activity_name": "Implement REST API for Rabbit binder cleanup",
      "activity_description": "Port the RabbitBindingCleaner to a REST controller endpoint, integrate with existing REST API security, and add tests (U2).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A07",
      "activity_name": "Optimize YARN deployer for rapid deployment",
      "activity_description": "Profile and refactor YARN deployer to deploy stream and modules concurrently, reuse client connections, and validate performance with tests (U3).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A08",
      "activity_name": "Support Kafka bus partitioning key for single downstream module",
      "activity_description": "Modify Kafka bus configuration to allow a partition key expression even with one downstream module, leveraging native Kafka partitioning, and update tests (U6).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A09",
      "activity_name": "Document HSQL DB limitations for composed jobs",
      "activity_description": "Update the AsciiDoc user guide with limitations of HSQL DB when using composed jobs and note any workarounds (U8).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration testing and regression verification",
      "activity_description": "Run full project build, integration test suite, and verify all upgrades and features work together; fix defects found.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "Code review, documentation finalization, and release prep",
      "activity_description": "Self-review changes, finalize release notes/changelog, and prepare commit/PR for the increment.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 118
  }
}

